"""Synthetic only: no source path, gzip, SQLite, classifier or tokenizer invocation."""
import copy
import hashlib
import json
import component_core as c

def ident(t):
    return dict(source_id=1,ordinal=7,text_SHA256=hashlib.sha256(t.encode()).hexdigest(),source_JSON_SHA256='b'*64)
def run(t):
    i=ident(t);old=copy.deepcopy(i);d=c.detect_components(t,i)
    assert i==old and d['source_text_unchanged'] and d['new_admission'] is False
    assert d['automatic_candidate_exclusion'] is False and d['unmarked_rights_and_human_authorship']=='UNASSESSED_NOT_CLEARED'
    for f in d['flags']:
        a,b=f['char_span'];x,y=f['UTF8_span'];ca,cb=f['context_char_span'];cx,cy=f['context_UTF8_span']
        assert t[a:b]==f['raw'] and t.encode()[x:y]==f['raw'].encode()
        assert t[ca:cb]==f['context_raw'] and t.encode()[cx:cy]==f['context_raw'].encode()
        assert hashlib.sha256(f['raw'].encode()).hexdigest()==f['raw_SHA256']
        assert hashlib.sha256(f['context_raw'].encode()).hexdigest()==f['context_SHA256']
        assert f['component_extent']=='UNKNOWN_NOT_THE_NOTICE_SPAN' and not f['automatic_candidate_exclusion'] and not f['confirms_generated_retained_body']
    return d

def kinds(t):return {f['kind'] for f in run(t)['flags']}
def refuse(fn,fragment):
    try:fn()
    except (ValueError,UnicodeError) as e:assert fragment in str(e),(e,fragment)
    else:raise AssertionError('expected refusal:'+fragment)

results=[]
